"""Exact frozen W4-to-INT8 fold, performed once at load time.
Derived from staged_visual / MLX PR4722, same MIT provenance.
"""
import mlx.core as mx
from . import staged_visual as sv
coeff = mx.fast.metal_kernel(name='wam_fold_coeff', input_names=['scales', 'biases', 'w_inv'], output_names=['a', 'b'], header=sv.header, source='uint i=thread_position_in_grid.x; if(i>=scales_shape[0]*scales_shape[1])return; float inv=w_inv[i/scales_shape[1]]; a[i]=int(rint(float(scales[i])*inv)); b[i]=int(rint(float(biases[i])*inv))+(1<<(QMM_I8_FRAC-1));')
fold = mx.fast.metal_kernel(name='wam_fold_weights', input_names=['w', 'a', 'b'], output_names=['out'], header=sv.header, source='uint i=thread_position_in_grid.x; const int K=a_shape[1]*64; if(i>=w_shape[0]*K/4)return; uint row=i/(K/4),kk=(i%(K/4))*4; int4 q=qmm_i8_unpack4<4>((const device uint8_t*)w+row*K/2,kk/4); int4 v=(q*a[row*(K/64)+kk/64]+b[row*(K/64)+kk/64])>>QMM_I8_FRAC; ((device char4*)out)[i]=char4(v);')
kernel=mx.fast.metal_kernel(name="wam_prepacked_int8",input_names=["w","scales","biases","w_inv","w_scale","x8","x_scale","x_exp"],output_names=["y"],header=sv.header,source='uint3 tid=threadgroup_position_in_grid;uint lid=thread_index_in_threadgroup,simd_gid=simdgroup_index_in_threadgroup;const int K=XK,N=w_shape[0],M=ROWS;\n\n  constexpr int BM = 64;\n  constexpr int BN = 64;\n  constexpr int BK = 64;\n  constexpr int WM = 2;\n  constexpr int WN = 2;\n  constexpr int BK_padded = BK + 16;\n\n  // Each thread folds VPT weights of one row, all in one quantization group\n  constexpr int VPT = (BN * BK) / (WM * WN * SIMD_SIZE);\n  static_assert(\n      VPT % 8 == 0 && BK % VPT == 0 && group_size % VPT == 0,\n      "A thread stages whole packs of the weights within one group");\n\n  constexpr int pack_factor = get_pack_factor<bits, 8>();\n  constexpr int bytes_per_pack = get_bytes_per_pack<bits>();\n\n  threadgroup uint Ws_storage[(BN * BK_padded) / 4];\n  threadgroup int8_t* Ws = (threadgroup int8_t*)Ws_storage;\n\n  constexpr short SM = BM / WM;\n  constexpr short SN = BN / WN;\n  constexpr short SK = 32;\n\n  constexpr short TM = SM / 16;\n  constexpr short TN = SN / 16;\n  constexpr short TK = SK / 16;\n\n  const int y_row = tid.y * BM;\n  const int y_col = tid.x * BN;\n  const short tm = SM * (simd_gid / WN);\n  const short tn = SN * (simd_gid % WN);\n\n  // The part of the weight tile this thread stages\n  const int nl = lid / (BK / VPT);\n  const int kl = (lid % (BK / VPT)) * VPT;\n  const int n = y_col + nl;\n  const bool valid = n < N;\n\n  threadgroup int8_t* dst = Ws + nl * BK_padded + kl;\n  const device uint8_t* wl = (const device uint8_t*)w;\n  float inv = 0.0f;\n  if (valid) {\n    wl += size_t(n) * K;\n    scales += size_t(n) * (K / group_size);\n    biases += size_t(n) * (K / group_size);\n    inv = w_inv[n];\n  } else {\n    for (int i = 0; i < VPT / 4; i++) {\n      *(threadgroup uint*)(dst + 4 * i) = 0;\n    }\n  }\n\n  // x8 has one BM x BK block per row tile and BK columns of K\n  x8 += (size_t(tid.y) * (K / BK) * BM + tm) * BK;\n\n  // A thread has 8 values of the accumulator for each of 4 rows\n  constexpr int exp_ld = BaseNAXFrag::kElemRowsJump;\n  const int x_exp_stride = K / BK + 1;\n  x_exp += size_t(y_row + tm + BaseNAXFrag::get_coord().y) * x_exp_stride;\n\n  NAXTile<int32_t, TM, TN> Dtile;\n  Dtile.clear();\n\n  for (int k = 0; k < K; k += BK) {\n    threadgroup_barrier(mem_flags::mem_threadgroup);\n\n    if (valid) {\n      const int kk = k + kl;\n      const int a = int(scales[kk / group_size]);\n      const int b = int(biases[kk / group_size]);\n      const device uint8_t* p = wl + kk;\n\n      STEEL_PRAGMA_UNROLL\n      for (int i = 0; i < VPT / 4; i++) {\n        const int4 v = int4(*(const device char4*)(p + 4*i));\n        *(threadgroup uint*)(dst + 4 * i) = as_type<uint>(char4(v));\n      }\n    }\n\n    threadgroup_barrier(mem_flags::mem_threadgroup);\n\n    // Move the accumulator of each row to the scale of this block of x. A\n    // fragment has 4 values for each of 2 rows.\n    constexpr int shift_every = x_span > 0 ? x_span : 1;\n    const bool shift = x_span > 0 && (k / BK) % shift_every == 0;\n    STEEL_PRAGMA_UNROLL\n    for (short i = 0; shift && i < TM; i++) {\n      typedef metal::vec<int32_t, BaseNAXFrag::kElemsPerFrag> frag_t;\n      const device uint8_t* e0 =\n          x_exp + size_t(i * BaseNAXFrag::kFragRows) * x_exp_stride + k / BK;\n      const device uint8_t* e1 = e0 + size_t(exp_ld) * x_exp_stride;\n      const int s0 = int(e0[1]) - int(e0[0]);\n      const int s1 = int(e1[1]) - int(e1[0]);\n      const int l0 = max(s0, 0);\n      const int l1 = max(s1, 0);\n      const int r0 = max(-s0, 0);\n      const int r1 = max(-s1, 0);\n      const frag_t left = frag_t(l0, l0, l0, l0, l1, l1, l1, l1);\n      const frag_t right = frag_t(r0, r0, r0, r0, r1, r1, r1, r1);\n      const frag_t rounding = (frag_t(1) << right) >> 1;\n      STEEL_PRAGMA_UNROLL\n      for (short j = 0; j < TN; j++) {\n        Dtile.frag_at(i, j) =\n            ((Dtile.frag_at(i, j) << left) + rounding) >> right;\n      }\n    }\n\n    STEEL_PRAGMA_NO_UNROLL\n    for (int kk1 = 0; kk1 < BK; kk1 += SK) {\n      NAXTile<int8_t, TM, TK> Atile;\n      NAXTile<int8_t, TN, TK> Btile;\n\n      volatile int compiler_barrier;\n\n      Atile.load(x8 + kk1, BK);\n      Btile.template load<int8_t, BK_padded, 1>(Ws + tn * BK_padded + kk1);\n\n      tile_matmad_nax(\n          Dtile,\n          Atile,\n          metal::bool_constant<false>{},\n          Btile,\n          metal::bool_constant<true>{});\n\n      (void)compiler_barrier;\n    }\n\n    x8 += BM * BK;\n  }\n\n  // Guarded stores are slow, only use them at the edges of the output\n  const bool interior = (y_row + tm + SM <= M) && (y_col + tn + SN <= N);\n  dispatch_bool(interior, [&](auto kInterior) {\n    STEEL_PRAGMA_UNROLL\n    for (short i = 0; i < TM; i++) {\n      STEEL_PRAGMA_UNROLL\n      for (short j = 0; j < TN; j++) {\n        const auto frag = Dtile.frag_at(i, j);\n        STEEL_PRAGMA_UNROLL\n        for (short e = 0; e < BaseNAXFrag::kElemsPerFrag; e++) {\n          const short2 pos = BaseNAXFrag::get_coord(e);\n          const int r = y_row + tm + i * BaseNAXFrag::kFragRows + pos.y;\n          const int c = y_col + tn + j * BaseNAXFrag::kFragCols + pos.x;\n          if constexpr (kInterior.value) {\n            y[size_t(r) * N + c] =\n                static_cast<T>(float(frag[e]) * x_scale[r] * w_scale[c]);\n          } else if (r < M && c < N) {\n            y[size_t(r) * N + c] =\n                static_cast<T>(float(frag[e]) * x_scale[r] * w_scale[c]);\n          }\n        }\n      }\n    }\n  });\n')
class PrepackedVisual(sv.StagedVisual):

    def __init__(self, orig):
        mode = "int8"
        self.w = dict(orig.w)
        self.packed = {}
        self.mode = mode
        self.info = dict(orig.info, kind="mixed_bf16_prepacked_int8", weight_bits=8, source_weight_bits=4, storage="int8", prepacked=True)
        for key, (w, s, b, wi, ws) in orig.packed.items():
            a, z = coeff(inputs=[s, b, wi], grid=(s.size, 1, 1), threadgroup=(256, 1, 1), output_shapes=[s.shape, b.shape], output_dtypes=[mx.int32, mx.int32])
            mx.eval(a, z)
            if mode == 'int8':
                w = fold(inputs=[w, a, z], grid=(w.shape[0] * s.shape[1] * 16, 1, 1), threadgroup=(256, 1, 1), output_shapes=[(w.shape[0], s.shape[1] * 64)], output_dtypes=[mx.int8])[0]
                mx.eval(w)
            self.packed[key] = (w, a, z, wi, ws)

    def linear(self, x, p):
        if p not in self.packed:
            return sv.RopeWeights.linear(self, x, p)
        shape = x.shape
        x = x.reshape(-1, shape[-1])
        m, k = x.shape
        parts = self.packed[p]
        n = parts[0].shape[0]
        a, s, e = sv.quantize(x)
        y = kernel(inputs=[*parts, a, s, e], template=[('T', x.dtype), ('group_size', 64), ('bits', 4), ('x_span', 0), ('XK', k), ('ROWS', m)], grid=((n + 63) // 64 * 128, (m + 63) // 64, 1), threadgroup=(128, 1, 1), output_shapes=[(m, n)], output_dtypes=[x.dtype])[0].reshape(*shape[:-1], n)
        bias = self.w.get(p + '.bias')
        return y if bias is None else y + bias
